import Database from 'better-sqlite3';

const dbPath = '/home/user/qwik-app/database.sqlite';

let db: Database.Database | null = null;

export function getDB(): Database.Database {
  if (!db) {
    db = new Database(dbPath);
    // Ensure table exists
    db.exec(`
      CREATE TABLE IF NOT EXISTS users (
        id INTEGER PRIMARY KEY AUTOINCREMENT,
        name TEXT NOT NULL,
        email TEXT NOT NULL,
        age INTEGER NOT NULL
      )
    `);
  }
  return db;
}

/**
 * Robust RFC-4180 compliant CSV parser.
 * Handles commas, double quotes, escaped quotes (""), and newlines inside quotes.
 */
export function parseCSV(text: string): string[][] {
  const result: string[][] = [];
  let row: string[] = [];
  let inQuotes = false;
  let currentField = '';

  let i = 0;
  while (i < text.length) {
    const char = text[i];
    const nextChar = text[i + 1];

    if (inQuotes) {
      if (char === '"') {
        if (nextChar === '"') {
          // Escaped quote
          currentField += '"';
          i += 2;
        } else {
          // Closing quote
          inQuotes = false;
          i += 1;
        }
      } else {
        currentField += char;
        i += 1;
      }
    } else {
      if (char === '"') {
        inQuotes = true;
        i += 1;
      } else if (char === ',') {
        row.push(currentField);
        currentField = '';
        i += 1;
      } else if (char === '\r' && nextChar === '\n') {
        row.push(currentField);
        result.push(row);
        row = [];
        currentField = '';
        i += 2;
      } else if (char === '\n') {
        row.push(currentField);
        result.push(row);
        row = [];
        currentField = '';
        i += 1;
      } else if (char === '\r') {
        row.push(currentField);
        result.push(row);
        row = [];
        currentField = '';
        i += 1;
      } else {
        currentField += char;
        i += 1;
      }
    }
  }

  // Handle the last field and row if the file didn't end with a newline
  if (currentField !== '' || row.length > 0 || (i > 0 && text[i - 1] === ',')) {
    row.push(currentField);
    result.push(row);
  }

  // If the last row is empty (e.g. trailing newline), filter it out
  if (result.length > 0 && result[result.length - 1].length === 1 && result[result.length - 1][0] === '') {
    result.pop();
  }

  return result;
}

import type { RequestHandler } from '@builder.io/qwik-city';
import { getDB } from '../../lib/db';
import { parseCSV } from '../../lib/csv';

export const onPost: RequestHandler = async ({ request, json }) => {
  try {
    const formData = await request.formData();
    const file = formData.get('file');

    if (!file || typeof file === 'string') {
      return json(200, {
        success: false,
        imported: 0,
        errors: [
          {
            row: 1,
            errors: ["No file uploaded or invalid file field"]
          }
        ]
      });
    }

    let text = await file.text();
    if (text.startsWith('\ufeff')) {
      text = text.slice(1);
    }

    const rows = parseCSV(text);
    if (rows.length === 0) {
      return json(200, {
        success: false,
        imported: 0,
        errors: [
          {
            row: 1,
            errors: ["CSV file is empty"]
          }
        ]
      });
    }

    const headers = rows[0].map(h => h.trim());
    const nameIdx = headers.indexOf('Name');
    const emailIdx = headers.indexOf('Email');
    const ageIdx = headers.indexOf('Age');

    if (nameIdx === -1 || emailIdx === -1 || ageIdx === -1) {
      return json(200, {
        success: false,
        imported: 0,
        errors: [
          {
            row: 1,
            errors: ["Missing required CSV columns (Name, Email, Age)"]
          }
        ]
      });
    }

    const allErrors: { row: number; errors: string[] }[] = [];
    const validUsers: { name: string; email: string; age: number }[] = [];

    // Skip header row at rows[0]
    for (let i = 1; i < rows.length; i++) {
      const row = rows[i];

      // Skip completely empty rows
      if (row.length === 0 || (row.length === 1 && row[0].trim() === '')) {
        continue;
      }

      const name = (row[nameIdx] !== undefined ? row[nameIdx] : '').trim();
      const email = (row[emailIdx] !== undefined ? row[emailIdx] : '').trim();
      const ageStr = (row[ageIdx] !== undefined ? row[ageIdx] : '').trim();

      const rowErrors: string[] = [];

      // 1. Name validation
      if (!name) {
        rowErrors.push("Name cannot be empty");
      }

      // 2. Email validation
      const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
      if (!email || !emailRegex.test(email)) {
        rowErrors.push("Invalid email format");
      }

      // 3. Age validation
      if (!ageStr || !/^\d+$/.test(ageStr)) {
        rowErrors.push("Age must be an integer >= 0");
      }

      if (rowErrors.length > 0) {
        allErrors.push({
          row: i, // 1-based index of the data row excluding the header
          errors: rowErrors
        });
      } else {
        validUsers.push({
          name,
          email,
          age: parseInt(ageStr, 10)
        });
      }
    }

    if (allErrors.length > 0) {
      // Sort errors by row ascending (already sorted, but sort explicitly to be absolutely sure)
      allErrors.sort((a, b) => a.row - b.row);
      return json(200, {
        success: false,
        imported: 0,
        errors: allErrors
      });
    }

    // Atomically insert users
    const db = getDB();
    const insertUser = db.prepare('INSERT INTO users (name, email, age) VALUES (?, ?, ?)');

    const insertMany = db.transaction((usersList: typeof validUsers) => {
      for (const user of usersList) {
        insertUser.run(user.name, user.email, user.age);
      }
    });

    insertMany(validUsers);

    return json(200, {
      success: true,
      imported: validUsers.length,
      errors: []
    });

  } catch (error: any) {
    return json(200, {
      success: false,
      imported: 0,
      errors: [
        {
          row: 1,
          errors: [error?.message || "An unexpected error occurred during import"]
        }
      ]
    });
  }
};

import type { RequestHandler } from '@builder.io/qwik-city';
import { getDB } from '../../lib/db';

export const onGet: RequestHandler = async ({ json }) => {
  try {
    const db = getDB();
    const users = db.prepare('SELECT id, name, email, age FROM users ORDER BY id ASC').all();
    return json(200, users);
  } catch (error: any) {
    return json(500, {
      error: error?.message || "An unexpected error occurred while retrieving users"
    });
  }
};

